#!/usr/bin/env python3
"""
write_receipt.py (The "Runner" / Worker Node)

Simulates a GPU testing node writing test results back to the central State Store.
"""

import sys
import hashlib
import os
from datetime import datetime
import psycopg2

if __name__ == "__main__":
    # 1. Establish connection to the broker via the network alias 'db-server'
    db_host = sys.argv[1] if len(sys.argv) > 1 else "db-server"

    try:
        print(f"\n>>> [Runner] Writing test results to {db_host}...")

        # 2. Create a mock artifact (simulating a large test.log generated by the GPU run)
        artifact_content = (
            b"This is a simulated heavy ROCm log file containing GPU memory traces..."
        )

        # 3. Generate the content-addressed SHA-256 receipt (Section 7 Invariant #2)
        sha256_hash = hashlib.sha256(artifact_content).hexdigest()

        # 4. Save the artifact to a local mount point (simulating our /rocm-db/artifacts store)
        save_path = f"/mnt/artifacts/log-{sha256_hash[:12]}.txt"
        os.makedirs("/mnt/artifacts", exist_ok=True)
        with open(save_path, "wb") as f:
            f.write(artifact_content)

        # 5. Write the metadata receipt to PostgreSQL (The actual broker interaction)
        conn = psycopg2.connect(host=db_host, dbname="artifact_state", user="mydbuser")

        with conn.cursor() as cur:
            print("    [Runner] Saving receipt for job 'test-fedora-r44-002'...")
            cur.execute(
                """
                INSERT INTO run_receipts (job_id, status, log_sha256, log_path)
                VALUES (%s, %s, %s, %s);
                """,
                ("test-fedora-r44-002", "passed", sha256_hash, save_path),
            )

            conn.commit()

        conn.close()
        cur.close()
        print("    [Runner] Receipt confirmed by broker. Job complete.")

    except Exception as e:
        print(
            f"[CRITICAL ERROR] Runner failed to communicate with the State Store: {e}"
        )
        sys.exit(1)
